html:
{%- import 'afintrix_theme/templates/print/afintrix_print.html' as afx -%}
<div class="afx-print">
	{{ afx.head(_('Delivery Note'), doc.name, [
		(_('Date'), frappe.utils.formatdate(doc.posting_date)),
		(_('Order'), doc.items[0].against_sales_order if doc.items else none),
	]) }}

	{{ afx.parties([
		(_('Deliver to'), doc.customer_name, doc.shipping_address or doc.address_display or ''),
		(_('From'), doc.company, doc.company_address_display or ''),
	]) }}

	{{ afx.table_open([
		(_('Item'), '58%', 'left'),
		(_('Qty'), '18%', 'right'),
		(_('UOM'), '20%', 'right'),
	]) }}
	{%- for row in doc.items %}
	<tr>
		<td>{{ loop.index }}</td>
		{{ afx.item_cell(row.item_name, row.description) }}
		<td class="text-right">{{ row.qty }}</td>
		<td class="text-right">{{ row.uom or '' }}</td>
	</tr>
	{%- endfor %}
	{{ afx.table_close() }}

	{{ afx.terms(_('Terms'), doc.terms) }}
	{{ afx.signatures(_('Delivered by'), _('Received by')) }}
</div>
